# ac5, like t102's, rejects a candidate only on the card and the groom handoff.
DELIVERABLES = [".gitignore", "docs/commands.md", "docs/tools/leg_path_pin_audit.py",
                "docs/state/outputs/t104_hygiene_findings.json"]
FROZEN = ["docs/state/merge_test_index.json", "README.md", "openapi.yaml",
          "docs/requirements.md", "docs/issues/t78.md", "docs/issues/t103.md",
          "docs/criteria/agent_pack_verification.md", "docs/criteria/req_coverage_verification.md",
          "docs/criteria/docs_verification.md", "docs/criteria/dashboard_verification.md",
          "docs/criteria/infra_verification.md", "docs/criteria/security_ops_verification.md",
          "docs/plan.md", "docs/backlog.md", "docs/state/dag.json", "docs/state/dag.mmd",
          "docs/state/issue_map.json", "docs/state/merge_history.json",
          "backend/scripts/agent_pack_verification.py", "backend/scripts/req_coverage_verification.py"]
FORBIDDEN_PREFIXES = ("src/", "frontend/src/", "scripts/", "launcher/", "schemas/",
                      "skills/", "e2e/", "ops/", "observability/", "security/",
                      "custom-agent/", "mcp-server/", "agent-hooks/", "agent-capabilities/",
                      "backend/")
KEYS = ("GIT_DIR", "GIT_WORK_TREE", "GIT_INDEX_FILE", "GIT_OBJECT_DIRECTORY",
        "GIT_COMMON_DIR", "GIT_PREFIX")
def fail(m):
    sys.stderr.write("ac5 RED: " + m + "\n"); raise SystemExit(1)
def cr(b):
    return b.replace(b"\r\n", b"\n")
def env():
    return {k: v for k, v in os.environ.items() if k not in KEYS}
def git(args):
    p = subprocess.run(["git"] + args, capture_output=True, env=env())
    return cr(p.stdout or b""), (p.stderr or b"").decode("utf-8", "replace"), p.returncode
def rev(spec):
    out, _, _ = git(["rev-parse", "--revs-only", spec])
    r = out.decode("utf-8", "replace").strip()
    return r if r else ""
def merge_base(ref):
    if not rev(ref):
        return ""
    out, _, _ = git(["merge-base", ref, "HEAD"])
    b = out.decode("utf-8", "replace").strip()
    return b if b else ""
def blob(rev_, path):
    out, err, _ = git(["show", "%s:%s" % (rev_, path)])
    if not out:
        w = subprocess.run(["wslpath", "-w", os.getcwd()], capture_output=True,
                           text=True, env=env()).stdout.strip().replace("\r\n", "\n")
        out, err, _ = git(["cmd.exe", "/d", "/c", "git -C %s show %s:%s" % (w, rev_, path)])
    if not out:
        fail("blob %s:%s unreadable through WSL git AND cmd.exe git (%s)" % (rev_, path, err[:120]))
    return out
def blob_at(rev_, path):
    probe, _, rc = git(["rev-parse", "--verify", "-q", "%s:%s" % (rev_, path)])
    if rc != 0 or not probe.strip():
        return None
    return blob(rev_, path)
def work(path):
    if not os.path.isfile(path):
        fail("%s vanished from the tree" % path)
    return cr(open(path, "rb").read())
def rejection(cand):
    if not cand:
        return "unresolvable on this checkout"
    if cand == rev("HEAD"):
        return "is HEAD itself, not a base"
    _, _, rc = git(["merge-base", "--is-ancestor", cand, "HEAD"])
    if rc != 0:
        return "is not an ancestor of HEAD"
    for p in DELIVERABLES:
        at, head = blob_at(cand, p), blob_at("HEAD", p)
        if at is not None and head is not None and at == head:
            return "%s already equals its HEAD blob there - that commit carries this card's PRODUCT, so the delta would be vacuous (the card and the groom handoff are NOT rejection material: they ride the groom-ingest commit, which always sits between the base and the product)" % p
    return ""
CANDS = [("HEAD^ (the branch parent)", rev("HEAD^")),
         ("merge-base(main, HEAD)", merge_base("main")),
         ("merge-base(origin/main, HEAD)", merge_base("origin/main"))]
BASE = LABEL = ""
for label, cand in CANDS:
    if BASE:
        continue
    why = rejection(cand)
    if why:
        print("ac5 evidence: base candidate %s -> %s rejected: %s" % (label, cand[:7] or "(none)", why))
    else:
        BASE, LABEL = cand, label
        print("ac5 evidence: base candidate %s -> %s ACCEPTED (strict pre-product ancestor of HEAD)" % (label, cand[:7]))
if not BASE:
    fail("no candidate base is a strict pre-product ancestor of HEAD - the branch carries no product delta at all, so the hygiene edit has not been committed; name the branch shape and re-groom rather than pin a literal")
print("ac5 evidence: FROZENNESS BASE = %s derived from %s - no main-tip-at-groom literal is pinned" % (BASE[:7], LABEL))
for p in FROZEN:
    at = blob_at(BASE, p)
    if at is None:
        fail("%s does not exist at the derived base %s - it is a frozen neighbour and must predate this card" % (p, BASE[:7]))
    b, w = cr(at), work(p)
    if b != w:
        fail("%s differs from its %s blob (base %s vs work %s) - docs/state/merge_test_index.json is ORCHESTRATOR-OWNED and this card documents and checks it, never patches it; the same goes for README, openapi, requirements, the six criteria documents (t103's surface), the bookkeeping and both generators"
             % (p, BASE[:7], hashlib.sha256(b).hexdigest()[:12], hashlib.sha256(w).hexdigest()[:12]))
print("ac5 evidence: %d frozen neighbours byte-identical to their %s blobs" % (len(FROZEN), BASE[:7]))
if not os.path.isfile("docs/issues/t78.md"):
    fail("docs/issues/t78.md is not in the live dir - the leg-279 exemption is documented, never silently undone by this card")
print("ac5 evidence: the docs/issues/t78.md live exemption is intact")
out, err, rc = git(["diff", "--name-only", BASE])
if rc != 0:
    fail("git diff --name-only %s failed: %s" % (BASE[:7], err[:160]))
delta = [p for p in out.decode("utf-8", "replace").split("\n") if p.strip()]
codes = [p for p in delta if p.startswith(FORBIDDEN_PREFIXES) or "/tests/" in p or p.endswith((".py", ".ts", ".tsx"))]
codes = [c for c in codes if c != "docs/tools/leg_path_pin_audit.py"]
if codes:
    fail("the delta touches code/test paths (%s) beyond this card's own checker - a hygiene card ships documentation, an ignore rule, a checker and a record; it does not touch product code" % ", ".join(sorted(set(codes))[:8]))
print("ac5 evidence: delta against %s names %d path(s) and contains no product code or test path" % (BASE[:7], len(delta)))
absent = [p for p in DELIVERABLES if not os.path.isfile(p)]
if absent:
    fail("%s missing from the tree - the hygiene deliverables must all be present" % ", ".join(absent))
print("ac5 evidence: all four deliverables are present in the tree")
print("ac5 GREEN: CUSTODY INTACT - %d frozen neighbours (led by the orchestrator-owned merge-test index) are byte-identical to their %s blobs, the t78 exemption is live, all four deliverables are present, and the delta carries no product code" % (len(FROZEN), BASE[:7]))
PYAC5
